         <p class="subhead">Select one option below so we can tailor notifications to your preference.</p>
       </header>

       <section class="card" aria-labelledby="notification-preference-title">
         <form id="preferences-form" novalidate>
           <div class="form-field">
             <fieldset aria-describedby="notification-help">
               <legend id="notification-preference-title">
                 How do you prefer to receive notifications?
                 <span class="required" aria-hidden="true">*</span>
               </legend>
               <p class="help" id="notification-help">Choose one. You can change this later in your account settings.</p>

               <div class="options">
                 <label class="radio-option">
                   <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                   <span>Email</span>
                 </label>
                 <label class="radio-option">
                   <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                   <span>SMS</span>
                 </label>
                 <label class="radio-option">
                   <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                   <span>Push Notifications</span>
                 </label>
               </div>
             </fieldset>
           </div>

           <div class="actions">
             <button type="submit">Save preference</button>
             <p class="status" id="notification-status" role="status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     </div>
   </main>

   <script>
     const form = document.getElementById('preferences-form');
     const status = document.getElementById('notification-status');
     const radios = Array.from(form.querySelectorAll('input[name="notificationPreference"]'));

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const selected = form.elements.namedItem('notificationPreference').value;
       if (!selected) {
         status.textContent = 'Please choose a notification preference before saving.';
         status.dataset.state = 'error';
         radios[0].focus();
         return;
       }

       status.textContent = `Preference saved: ${selected}.`;
       status.dataset.state = 'success';
     });
   </script>
